<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch,toRaw} from 'vue'
import type {BackendController} from './use-backend.ts'
import {operationIdV1} from './api/browser-crypto.ts'
import {validateFulfillmentInput,type FulfillmentAttempt,type FulfillmentResult,type CreateTermsRequest,type RegisterTermsRequest,type AcknowledgeTermsRequest,type SettleTermsRequest,type CurrentActionProjection,type CurrentActionItem} from './api/commitment-fulfillment.ts'
import type {CommitmentCommandAttempt} from './api/commitment-communication.ts'
const props=defineProps<{backend:BackendController}>()
const activity=ref(''),budget=ref(''),audience=ref(''),roots=ref(''),source=ref(''),c02=ref('')
const commitmentId=ref(''),target=ref(''),literal=ref(''),establishment=ref<'unilateral'|'bilateral'>('unilateral'),fulfillmentKind=ref<'communicated'|'recipient_acknowledged'>('communicated')
const deadline=ref(''),role=ref<'offer'|'performance'>('offer'),validUntil=ref(''),offerReceipt=ref(''),inboundAck=ref(''),performanceReceipt=ref(''),recipientAck=ref('')
const actionRef=ref(''),actionProjection=ref<CurrentActionProjection|null>(null),cancelAcknowledged=ref(false)
let actionSelectionRevision=0
const acknowledged=ref(false),busy=ref(false),message=ref(''),scopeMetadata=ref(''),dispatchResult=ref<{operation_id:string;job_ref:string;outbox_ref:string}|null>(null)
const pending=computed(()=>props.backend.fulfillment.pending.value),current=computed(()=>props.backend.fulfillment.current.value),approval=computed(()=>props.backend.fulfillment.approval.value),sendPending=computed(()=>props.backend.commitments.pending.value)
const eligible=computed(()=>props.backend.canRead.value&&props.backend.runtimeReadable.value&&!busy.value),available=computed(()=>eligible.value&&!pending.value&&!sendPending.value)
let generation=0
function clear(){++generation;activity.value=budget.value=audience.value=roots.value=source.value=c02.value='';commitmentId.value=target.value=literal.value=deadline.value=validUntil.value='';offerReceipt.value=inboundAck.value=performanceReceipt.value=recipientAck.value='';acknowledged.value=false;scopeMetadata.value='';message.value='';dispatchResult.value=null;actionRef.value='';actionProjection.value=null;cancelAcknowledged.value=false}
watch(()=>[props.backend.state.scope,props.backend.state.auth,props.backend.state.owner,props.backend.runtimeReadable.value],clear,{flush:'sync'})
watch(approval,()=>{acknowledged.value=false;dispatchResult.value=null})
watch(actionRef,()=>{++actionSelectionRevision;actionProjection.value=null;cancelAcknowledged.value=false},{flush:'sync'})
watch(()=>props.backend.commitments.lastAction.value,value=>{if(value)actionRef.value=value.ref},{immediate:true})
onBeforeUnmount(()=>{++generation})
const stillCurrent=(token:number,scope:string)=>token===generation&&scope===props.backend.state.scope&&props.backend.canRead.value
const expiry=(value:number)=>new Date(value*1000).toISOString()
function timestamp(value:string){const time=Date.parse(value)/1000;if(!Number.isFinite(time))throw new Error('请选择明确有效的本地时间。');return time}
function envelope(request:CreateTermsRequest|RegisterTermsRequest|AcknowledgeTermsRequest|SettleTermsRequest){return {activity_id:activity.value,audience_ref:audience.value,parent_budget_lease_ref:budget.value,request}}
function apply(result:FulfillmentResult){
 if(result.kind==='transition'){props.backend.fulfillment.current.value=result.view;props.backend.fulfillment.approval.value=null;message.value='已取得同次提交的条款转换元数据。当前状态：'+result.view.establishment_state+' / '+result.view.fulfillment_state+'。'}
 else if(result.kind==='approval'){props.backend.fulfillment.approval.value=result.approval;scopeMetadata.value=result.metadata?.scope_ref??'';message.value=result.approval?'已取得本次获准 SourceWork 的完整渲染文本。请逐项核对，再明确进入发送准备。':'原授权提交已确认，本次仅返回 Scope 元数据。没有当前完整文本摘要，不能从 metadata 恢复文本或提交发送。'}
}
async function run(attempt:FulfillmentAttempt,replay=false){
 if(!eligible.value||attempt.scope!==props.backend.state.scope||!replay&&(pending.value||sendPending.value))return
 try{validateFulfillmentInput(attempt)}catch(error){message.value=error instanceof Error?error.message:'输入未通过合同核验，尚未提交。';return}
 const token=generation;if(!replay)props.backend.fulfillment.pending.value=attempt;busy.value=true;message.value=replay?'正在核验同一操作ID和原输入。':'正在独立核验当前 Owner、Source、版本和真实证据。'
 let received=false
 try{const result=await props.backend.fulfillment.run(attempt);received=true;if(props.backend.fulfillment.pending.value?.operationId===attempt.operationId)props.backend.fulfillment.pending.value=null;if(stillCurrent(token,attempt.scope)){if(result.kind==='cancel'){actionProjection.value=null;cancelAcknowledged.value=false;actionRef.value=result.action_ref;const observed=await props.backend.fulfillment.readAction(attempt.scope,[result.action_ref]);if(stillCurrent(token,attempt.scope)){actionProjection.value=observed;const item=observed.items[0];message.value=observed.coverage==='complete'&&item?.cancellation_ref===result.cancellation_ref&&item.cancellation_revision===result.cancellation_revision&&item.cancel_epoch>0?'独立回读与本次取消原件的实际版本一致。已交给平台的效果不会因此逆转。':'取消原件已确认；当前独立回读状态：'+(item?.cancellation_state??'未取得完整当前状态')+'，按当前实际版本显示。'}}else apply(result)}}catch{if(token===generation)message.value=received?'操作原件已确认；独立回读未完成，请明确重读当前状态，不再次提交。':'结果尚未确认，可能已提交。原操作ID和精确输入保留；请明确核验原请求，勿另建替代操作。'}finally{busy.value=false}
}
function replay(){const original=pending.value;if(original)void run(structuredClone(toRaw(original)),true)}
function attempt(kind:FulfillmentAttempt['kind'],request:CreateTermsRequest|RegisterTermsRequest|AcknowledgeTermsRequest|SettleTermsRequest){return {scope:props.backend.state.scope,kind,input:envelope(request),operationId:operationIdV1()}}
function create(){if(!available.value)return;try{void run(attempt('create_terms',{commitment_id:commitmentId.value,counterparty_ref:target.value,establishment_kind:establishment.value,source_refs:roots.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean),fulfillment_kind:fulfillmentKind.value,deliverable_literal:literal.value,deadline_utc:deadline.value?timestamp(deadline.value):null}))}catch(error){message.value=String(error)}}
function versions(){const v=current.value;if(!v)throw new Error('先取得真实创建或后续转换回执，不能填写默认对象版本。');return {current_commitment:{ref:v.commitment_ref,version:v.commitment_revision},terms:{ref:v.terms_ref,version:v.terms_revision}}}
function approve(){if(!available.value||!current.value)return;try{void run(attempt('approve_terms',{...versions(),source_ref:source.value,role:role.value,valid_until_utc:timestamp(validUntil.value)}))}catch(error){message.value=String(error)}}
function acknowledge(){if(!available.value||!current.value)return;void run(attempt('ack_terms',{...versions(),inbound_source_ref:inboundAck.value,outbound_offer_receipt_ref:offerReceipt.value}))}
function settle(){if(!available.value||!current.value)return;void run(attempt('settle_terms',{...versions(),performance_outbound_receipt_ref:performanceReceipt.value,recipient_ack_source_ref:recipientAck.value||null}))}
async function prepare(replay=false){
 let saved:CommitmentCommandAttempt
 if(replay){if(!sendPending.value||sendPending.value.kind!=='submit')return;saved=structuredClone(toRaw(sendPending.value))}
 else{if(!available.value||!approval.value||!acknowledged.value)return;const a=approval.value;if(a.valid_until_utc<=Date.now()/1000){message.value='该 Scope 已到期，不能延长原授权。';return}saved={scope:props.backend.state.scope,kind:'submit',operationId:operationIdV1(),input:{scope_ref:a.scope_ref,c02_operation_id:c02.value,source_ref:a.source_ref,deadline_utc:a.valid_until_utc}};props.backend.commitments.pending.value=saved}
 const token=generation;busy.value=true;try{const result=await props.backend.commitments.run(saved);if(result.kind!=='submit')return;if(props.backend.commitments.pending.value?.operationId===saved.operationId)props.backend.commitments.pending.value=null;if(stillCurrent(token,saved.scope)){dispatchResult.value=result;message.value='已取得真实发送准备、任务与发件箱原件。送达、对方接受和履约仍需实际证据核验。'}}catch{if(token===generation)message.value='发送准备结果尚未确认。请仅核验原操作ID与原 Scope，不新建替代请求。'}finally{busy.value=false}
}
async function readAction(){
 if(!eligible.value)return;const target=actionRef.value.trim();if(!target){message.value='请选择实际发送准备回执中的 Action 引用，或粘贴真实现有引用。';return}
 const token=generation,selection=actionSelectionRevision,scope=props.backend.state.scope;busy.value=true;actionProjection.value=null;cancelAcknowledged.value=false
 try{const result=await props.backend.fulfillment.readAction(scope,[target]);if(stillCurrent(token,scope)&&selection===actionSelectionRevision){actionProjection.value=result;message.value=result.coverage==='complete'?'已独立读取当前 Action 版本、实际 audience 与取消状态。':'当前元数据或实际 Source 依据不完整，不能取消。'}}catch{if(token===generation)message.value='未取得当前 Action 的完整授权元数据，未使用出生回执或默认版本替代。'}finally{busy.value=false}
}
const selectedAction=computed(()=>actionProjection.value?.coverage==='complete'&&actionProjection.value.items.length===1?actionProjection.value.items[0]!:null)
const canCancel=computed(()=>available.value&&!!budget.value&&cancelAcknowledged.value&&selectedAction.value?.state==='active'&&selectedAction.value.cancellation_state==='active'&&selectedAction.value.cancel_epoch===0)
function cancelAction(item:CurrentActionItem|null){if(!canCancel.value||!item||item!==selectedAction.value)return;void run({scope:props.backend.state.scope,kind:'cancel_action',operationId:operationIdV1(),purpose:item.purpose,input:{activity_id:item.activity_id,audience_ref:item.audience_ref,parent_budget_lease_ref:budget.value,request:{action_intent_ref:item.ref,expected_action_revision:item.action_revision}}})}
</script>
<template>
 <section class="fulfillment-owner" aria-labelledby="fulfillment-title" :aria-busy="busy">
  <h4 id="fulfillment-title">有明确条款的承诺与履约</h4><p>先冻结具体对象、完整交付文本、履约判据和可选期限。通信分为 offer 与 performance；实际送达、ACCEPT 和 RECEIVED 各自使用真实证据。</p>
  <p v-if="!backend.canRead.value">先核验当前所有者和角色范围。</p>
  <details><summary>当前实际活动、预算与 Source audience</summary><label>当前活动引用<input v-model="activity" :disabled="!available" autocomplete="off"></label><label>现有获准父预算引用<input v-model="budget" :disabled="!available" autocomplete="off"></label><label>Source 对应的实际会话 audience<input v-model="audience" :disabled="!available" autocomplete="off"></label><p>填写真实原件定位。来源目录的可见性不会自动授予此处的 expression 或通信权限。</p></details>
  <details open><summary>1 · 冻结新承诺条款</summary><label>新承诺标识（commitment: 开头）<input v-model="commitmentId" :disabled="!available"></label><label>具体对象引用（entity: 开头）<input v-model="target" :disabled="!available"></label><label>实际 Source 引用 · 每行一项，最多30项<textarea v-model="roots" rows="3" :disabled="!available" spellcheck="false"></textarea></label><label>承诺形式<select v-model="establishment" :disabled="!available"><option value="unilateral">单方承诺</option><option value="bilateral">双方约定，需要真实 ACCEPT</option></select></label><label>履约判据<select v-model="fulfillmentKind" :disabled="!available"><option value="communicated">实际 performance 已送达</option><option value="recipient_acknowledged">已送达且收到对方真实 RECEIVED</option></select></label><label>完整交付文本<textarea v-model="literal" maxlength="4096" rows="4" :disabled="!available"></textarea></label><p>原文最多2048字符，服务器还会核验渲染后的 offer/performance 总长。</p><label>可选截止时间（本地时间；留空表示无条款期限）<input v-model="deadline" type="datetime-local" step="1" :disabled="!available"></label><button :disabled="!available" @click="create">明确创建这份承诺与不可变条款</button></details>
  <article v-if="current"><h5>真实提交返回的当前选择</h5><dl><div><dt>承诺</dt><dd>{{current.commitment_ref}} · {{current.commitment_revision}}</dd></div><div><dt>条款</dt><dd>{{current.terms_ref}} · {{current.terms_revision}}</dd></div><div><dt>条款摘要</dt><dd>{{current.terms_digest}}</dd></div><div><dt>成立 / 履约状态</dt><dd>{{current.establishment_state}} / {{current.fulfillment_state}}</dd></div><div><dt>实际转换操作</dt><dd>{{current.operation_id}}</dd></div><div><dt>实际证据原件</dt><dd>{{current.evidence_ref}} · {{current.evidence_revision}}</dd></div></dl><p>版本来自实际回执；后续动作仍由后端重读当前版本并执行 CAS，旧回执不代表当前 head 永远有效。</p></article>
  <details><summary>2 · 登记条款通信 Scope</summary><p v-if="!current">先取得本界面创建或后续转换的真实回执。这里不推导或填写虚构 terms 引用。</p><label>本次实际入站路由 Source<textarea v-model="source" rows="2" :disabled="!available" spellcheck="false"></textarea></label><label>通信角色<select v-model="role" :disabled="!available"><option value="offer">offer · 提出条款</option><option value="performance">performance · 交付条款原文</option></select></label><label>本次 Scope 到期时间（本地时间）<input v-model="validUntil" type="datetime-local" step="1" :disabled="!available"></label><button :disabled="!available||!current" @click="approve">由服务器渲染并登记本次具体通信授权</button></details>
  <article v-if="approval"><h5>3 · 核对本次获准的完整渲染文本</h5><dl><div><dt>具体对象</dt><dd>{{approval.target_ref}}</dd></div><div><dt>实际平台 / 会话</dt><dd>{{approval.platform_ref}} / {{approval.conversation_ref}}</dd></div><div><dt>场景</dt><dd>{{approval.scene_ref}}</dd></div><div><dt>角色</dt><dd>{{approval.role}}</dd></div><div><dt>条款摘要</dt><dd>{{approval.terms_digest}}</dd></div><div><dt>实际路由 Source</dt><dd>{{approval.source_ref}}</dd></div><div><dt>Scope</dt><dd>{{approval.scope_ref}}</dd></div><div><dt>有效至</dt><dd>{{expiry(approval.valid_until_utc)}}</dd></div></dl><p class="literal">{{approval.approved_literal}}</p><label>同一实际入站来源的 C02 操作ID<input v-model="c02" :disabled="!available"></label><label class="check"><input v-model="acknowledged" type="checkbox" :disabled="!available">我已核对具体对象、完整渲染文本和同一 Scope，明确提交该通信。</label><button :disabled="!available||!acknowledged||!c02" @click="prepare()">明确进入正式发送准备</button></article>
  <p v-else-if="scopeMetadata">已确认的 Scope 元数据：{{scopeMetadata}}。没有批准正文摘要，不能发送。</p>
  <details><summary>4 · 用真实 ACCEPT / performance / RECEIVED 证据核验</summary><label>实际 offer 的 outbound receipt 引用<textarea v-model="offerReceipt" rows="2" :disabled="!available"></textarea></label><label>真实 ACCEPT 入站 Source 引用<textarea v-model="inboundAck" rows="2" :disabled="!available"></textarea></label><button :disabled="!available||!current||!offerReceipt||!inboundAck" @click="acknowledge">核验对方完整 ACCEPT 并提交成立证据</button><label>实际 performance outbound receipt 引用<textarea v-model="performanceReceipt" rows="2" :disabled="!available"></textarea></label><label>实际 RECEIVED 入站 Source（communicated 判据可留空）<textarea v-model="recipientAck" rows="2" :disabled="!available"></textarea></label><button :disabled="!available||!current||!performanceReceipt" @click="settle">核验实际履约证据并结算当前承诺</button><p>ACCEPT 不充当 RECEIVED。按钮、prepare 回执和手填引用均不能自行证明已送达或已履约。</p></details>
  <div v-if="pending" role="status"><p>原操作ID：{{pending.operationId}} · {{pending.kind}}</p><button :disabled="!eligible" @click="replay">核验原操作与原输入（保持操作ID）</button></div>
  <div v-if="sendPending?.kind==='submit'" role="status"><p>原发送准备操作ID：{{sendPending.operationId}}</p><button :disabled="!eligible" @click="prepare(true)">核验原发送准备与同一 Scope</button></div>
  <dl v-if="dispatchResult"><div><dt>发送准备操作</dt><dd>{{dispatchResult.operation_id}}</dd></div><div><dt>任务</dt><dd>{{dispatchResult.job_ref}}</dd></div><div><dt>发件箱</dt><dd>{{dispatchResult.outbox_ref}}</dd></div></dl>
  <details><summary>取消已选择的实际 Action</summary><p>发送准备回执只提供出生候选。先独立读取当前 Action 与取消 head，确认后才可提交取消；这不会逆转已交给平台的效果。</p><label>实际 Action 引用<textarea v-model="actionRef" rows="2" :disabled="!eligible||!!pending||!!sendPending" spellcheck="false"></textarea></label><button :disabled="!eligible||!actionRef" @click="readAction">独立读取当前 Action 与取消状态</button><article v-if="selectedAction"><dl><div><dt>Action / 当前版本</dt><dd>{{selectedAction.action_id}} / {{selectedAction.action_revision}}</dd></div><div><dt>实际活动</dt><dd>{{selectedAction.activity_id}}</dd></div><div><dt>原 purpose / audience</dt><dd>{{selectedAction.purpose}} / {{selectedAction.audience_ref}}</dd></div><div><dt>取消 head</dt><dd>{{selectedAction.cancellation_ref}} · {{selectedAction.cancellation_revision}}</dd></div><div><dt>当前状态 / epoch</dt><dd>{{selectedAction.cancellation_state}} / {{selectedAction.cancel_epoch}}</dd></div></dl><label class="check"><input v-model="cancelAcknowledged" type="checkbox" :disabled="!available||selectedAction.cancellation_state!=='active'||selectedAction.cancel_epoch!==0">我明确取消这个实际 Action 的后续执行，并保留未知或已交付效果的真实状态。</label><button :disabled="!canCancel" @click="cancelAction(selectedAction)">按当前实际版本提交取消，再独立回读</button></article><ul v-if="actionProjection?.missing_inputs.length"><li v-for="reason in actionProjection.missing_inputs" :key="reason">{{reason}}</li></ul></details>
  <p v-if="message" role="status" aria-live="polite">{{message}}</p>
 </section>
</template>
<style scoped>
.fulfillment-owner{font-size:12px;line-height:1.8;overflow-wrap:anywhere;margin-bottom:28px}h4{font-size:16px;font-weight:500;margin:0 0 14px}h5{font-size:13px;font-weight:500}p{color:var(--muted)}details,article{border-top:1px solid var(--line);padding:12px 0}summary{cursor:pointer;min-height:32px}label{display:grid;gap:7px;margin:12px 0}input,textarea,select{box-sizing:border-box;width:100%;min-height:42px;font:inherit;color:var(--ink);background:var(--surface);border:1px solid var(--line);padding:9px}textarea{resize:vertical}.check{display:flex;align-items:start;gap:10px}.check input{width:18px;min-height:18px;margin-top:3px}.literal{white-space:pre-wrap;padding:12px;border:1px solid var(--line)}dl>div{display:grid;grid-template-columns:100px 1fr;gap:12px;padding:7px 0;border-bottom:1px solid var(--line)}dd{margin:0}dt{color:var(--muted)}button{font:inherit;min-height:44px;width:100%;padding:10px 0;text-align:left;cursor:pointer}button:disabled{color:var(--muted);cursor:default}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid var(--ink);outline-offset:3px}
</style>
